window.__CADERNO_PARTS.push("{\"names\":{\"1\":\"Atendimento inicial — xABCDE\",\"2\":\"Choque hemorrágico\",\"3\":\"Transfusão maciça e controle de danos\",\"4\":\"Pré-hospitalar, triagem e transporte\",\"5\":\"Pneumotórax\",\"6\":\"Hemotórax\",\"7\":\"Fraturas costais e tórax instável\",\"8\":\"Contusão pulmonar e SDRA\",\"9\":\"Tamponamento cardíaco\",\"10\":\"Trauma cardíaco contuso e penetrante\",\"11\":\"Lesão traumática da aorta\",\"12\":\"Lesão traqueobrônquica, esofágica e diafragmática\",\"13\":\"Avaliação do trauma abdominal\",\"14\":\"Trauma hepático e esplênico\",\"15\":\"Trauma intestinal e mesentérico\",\"16\":\"Trauma pancreático e duodenal\",\"17\":\"Trauma retroperitoneal\",\"18\":\"Trauma pélvico\",\"19\":\"Trauma geniturinário\",\"20\":\"Traumatismo cranioencefálico\",\"21\":\"Trauma raquimedular\",\"22\":\"Trauma de extremidades / compartimental\",\"23\":\"Trauma vascular periférico\",\"24\":\"Trauma cervical\",\"25\":\"Trauma facial\",\"26\":\"Trauma por arma branca e arma de fogo\",\"27\":\"Trauma em gestantes\",\"28\":\"Trauma pediátrico\",\"29\":\"Trauma em idosos e anticoagulados\",\"30\":\"Queimaduras e trauma elétrico\",\"31\":\"Trauma por explosões\",\"32\":\"Afogamento, asfixia e lesões por inalação\",\"33\":\"Complicações pós-traumáticas\"},\"contents\":{\"1\":\"<h2 class=\\\"section-band\\\">01  •  AVALIAÇÃO INICIAL / XABCDE</h2>\\n<p class=\\\"subhead\\\">FICHA 01  |  Concluída  |  ATLS 11ª edição</p>\\n<h3>SEQUÊNCIA PRIMÁRIA E INTERVENÇÕES    ★ PROVA</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>ETAPA</th><th>O QUE AVALIAR</th><th>CONDUTA IMEDIATA</th></tr></thead><tbody><tr><td>x</td><td>Hemorragia exsanguinante</td><td>Compressão / tamponamento / torniquete</td></tr><tr><td>A</td><td>Patência e proteção da via aérea</td><td>Manobra com restrição cervical; IOT se indicada</td></tr><tr><td>B</td><td>Oxigenação e ventilação</td><td>Oxigênio; tratar pneumotórax hipertensivo</td></tr><tr><td>C</td><td>Perfusão e choque</td><td>Acesso IV/IO; fonte de sangramento; sangue</td></tr><tr><td>D</td><td>Glasgow, pupilas, déficits focais</td><td>Avaliação neurológica rápida e reavaliação</td></tr><tr><td>E</td><td>Exposição e ambiente</td><td>Examinar anterior/posterior; prevenir hipotermia</td></tr></tbody></table></div>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">VALORES PARA PROVA    ★ PROVA<br>•  Glasgow = 3–15; GCS ≤8 frequentemente requer via aérea definitiva, conforme contexto.<br>•  SpO₂ alvo inicial geralmente ≥94%; individualizar conforme lesões.<br>•  Hipotermia = temperatura central &lt;35 °C.<br>•  Torniquete: 5–8 cm proximal à ferida, nunca sobre articulação; apertar até cessar o sangramento.<br>TORNIQUETE E HEMOSTASIA<br>•  Compressão direta → tamponamento → torniquete se extremidade com hemorragia ameaçadora.<br>•  Reavaliar perfusão e sangramento; documentar horário do torniquete.</div><div class=\\\"note\\\">AMEAÇAS IMEDIATAS    ★ PROVA<br>•  Hemorragia externa maciça: tratar antes de completar A.<br>•  Pneumotórax hipertensivo: diagnóstico clínico e descompressão imediata, sem esperar imagem.<br>•  Hemorragia intra-abdominal em choque: controle cirúrgico sem atrasar para TC.<br>PEGADINHAS<br>•  eFAST negativo NÃO exclui hemorragia retroperitoneal, pélvica ou toda lesão abdominal.<br>•  Colar cervical NÃO substitui estabilização manual durante manejo de vias aéreas.<br>•  Repetir xABCDE sempre após mudança clínica ou intervenção.</div></div>\\n<h3>ALGORITMO DE BOLSO</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>30 SEGUNDOS</th><th>PRIORIDADE</th></tr></thead><tbody><tr><td>1</td><td>Controle a hemorragia exsanguinante</td></tr><tr><td>2</td><td>Garanta via aérea e oxigenação; proteja coluna quando indicado</td></tr><tr><td>3</td><td>Procure choque, tamponamento, pneumotórax hipertensivo e fontes hemorrágicas</td></tr><tr><td>4</td><td>Avalie Glasgow, pupilas e glicemia se pertinente</td></tr><tr><td>5</td><td>Exponha, aqueça, documente, reavalie xABCDE</td></tr></tbody></table></div>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">★ PROVA: NÃO realizar tomografia em paciente instável quando existe indicação de controle imediato da fonte hemorrágica.</div></div>\\n<p class=\\\"source\\\">FONTE: ATLS 11ª ed., capítulos 1 e 3–8. Técnicas torácicas detalhadas nos temas 5–12.</p>\\n<h2 class=\\\"section-band\\\">01  •  AVALIAÇÃO INICIAL / PEARLS</h2>\\n<p class=\\\"subhead\\\">FICHA 01  |  Algoritmos e conceitos de bolso</p>\\n<h3>DECISÕES RÁPIDAS    ★ PROVA</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>ACHADO</th><th>CONDUTA / RACIOCÍNIO</th></tr></thead><tbody><tr><td>Paciente fala normalmente</td><td>Via aérea provavelmente pérvia naquele momento; reavaliar</td></tr><tr><td>Sangramento intenso em membro</td><td>Compressão imediata; torniquete se necessário</td></tr><tr><td>Desconforto + hipotensão + murmúrio abolido unilateral</td><td>Pensar pneumotórax hipertensivo → descompressão</td></tr><tr><td>Hipotensão + eFAST positivo</td><td>Hemorragia intraperitoneal até prova em contrário → avaliar cirurgia urgente</td></tr><tr><td>Suspeita de fratura pélvica</td><td>Binder em trocânteres maiores, não na cintura</td></tr><tr><td>GCS caindo, secreções, sangue, incapacidade de proteção</td><td>Preparar via aérea definitiva com restrição de movimento cervical</td></tr><tr><td>Trauma grave com baixa temperatura</td><td>Cobrir/aquecer precocemente; minimizar exposição</td></tr></tbody></table></div>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">MONITORIZAÇÃO PRIMÁRIA<br>•  PA e FC seriadas, SpO₂, ECG; ETCO₂ para ventilação monitorizada se disponível.<br>•  Perfusão: pulsos, estado mental, pele, enchimento capilar e sangramento evidente.<br>•  Urina e lactato ajudam a acompanhar evolução, mas não devem atrasar intervenções.</div><div class=\\\"note\\\">LIMITAÇÕES CLÁSSICAS<br>•  Ausência de hipotensão não exclui hipoperfusão compensada.<br>•  Ausência de sangue externo não exclui sangramento volumoso oculto.<br>•  A avaliação secundária vem após ameaças imediatas controladas.<br>•  Paciente aparentemente estável pode deteriorar; reavaliar sempre.</div></div>\\n<h3>O QUE MEMORIZAR EM UMA FRASE</h3>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">x antes do ABCDE; tratar primeiro o que mata primeiro; reavaliar continuamente.</div></div>\\n<p class=\\\"source\\\">ATLS 11ª edição: fluxo inicial xABCDE e prioridades imediatas. Em trauma neurológico, metas e técnicas específicas serão retomadas nos temas 20–21.</p>\\n<section class=\\\"retro-practice\\\"><h2 class=\\\"section-band\\\">CASOS CLÍNICOS INTERATIVOS</h2><p class=\\\"subhead\\\">Casos adicionais de treino elaborados com base nos conceitos do ATLS 11. Os resultados dos exercícios abaixo são independentes das notas históricas.</p><details class=\\\"retro-case\\\"><summary>Caso 1 — Trauma torácico grave e choque inicial <span>3 questões</span></summary><div class=\\\"retro-case-content\\\"><p class=\\\"clinical\\\"><b>Vinheta:</b> Após queda de 7 metros, vítima chega com hemorragia externa pulsátil na coxa, FR 34, assimetria ventilatória e pulso periférico fraco.</p><section class=\\\"retro-quiz\\\" data-set=\\\"ps1_c1\\\"><h4>Resolva o caso antes de abrir a correção</h4><p class=\\\"retro-intro\\\"></p><div class=\\\"retro-q\\\" data-correct=\\\"A\\\"><b>1. Na abordagem inicial, qual ação é prioritária?</b><label><input type=\\\"radio\\\" name=\\\"ps1_c1_1\\\" value=\\\"A\\\"><span>A) Controle imediato da hemorragia exsanguinante</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c1_1\\\" value=\\\"B\\\"><span>B) Solicitar TC de corpo inteiro antes de tocar no paciente</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c1_1\\\" value=\\\"C\\\"><span>C) Completar exame neurológico detalhado antes de controlar sangue</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c1_1\\\" value=\\\"D\\\"><span>D) Imobilizar apenas a costela</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: A</b> — O x do xABCDE prioriza hemorragia externa ameaçadora à vida.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"B\\\"><b>2. Após controlar o sangramento e garantir via aérea, o que pesquisar no B?</b><label><input type=\\\"radio\\\" name=\\\"ps1_c1_2\\\" value=\\\"A\\\"><span>A) Apenas fraturas do antebraço</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c1_2\\\" value=\\\"B\\\"><span>B) Pneumotórax, hemotórax e efetividade da ventilação</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c1_2\\\" value=\\\"C\\\"><span>C) Glicemia e proteinúria</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c1_2\\\" value=\\\"D\\\"><span>D) Risco de trombose crônica</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: B</b> — B avalia respiração, oxigenação e lesões torácicas ameaçadoras.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"C\\\"><b>3. Se o paciente estiver instável com suspeita forte de pneumotórax hipertensivo, a prioridade é:</b><label><input type=\\\"radio\\\" name=\\\"ps1_c1_3\\\" value=\\\"A\\\"><span>A) Esperar angioTC</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c1_3\\\" value=\\\"B\\\"><span>B) Solicitar parecer ambulatorial</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c1_3\\\" value=\\\"C\\\"><span>C) Descomprimir clinicamente sem atraso por imagem</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c1_3\\\" value=\\\"D\\\"><span>D) Medir espirometria de incentivo</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: C</b> — Pneumotórax hipertensivo é diagnóstico clínico e requer descompressão emergencial.</div></div><button type=\\\"button\\\" class=\\\"retro-check\\\" data-retro-check>Corrigir respostas</button><button type=\\\"button\\\" class=\\\"retro-reset\\\" data-retro-reset>Refazer</button><p class=\\\"retro-result\\\" aria-live=\\\"polite\\\"></p></section></div></details><details class=\\\"retro-case\\\"><summary>Caso 2 — Choque com FAST positivo <span>3 questões</span></summary><div class=\\\"retro-case-content\\\"><p class=\\\"clinical\\\"><b>Vinheta:</b> Adulto com trauma abdominal contuso, PA 78/50, FC 140, pele fria, FAST positivo para líquido livre.</p><section class=\\\"retro-quiz\\\" data-set=\\\"ps1_c2\\\"><h4>Resolva o caso antes de abrir a correção</h4><p class=\\\"retro-intro\\\"></p><div class=\\\"retro-q\\\" data-correct=\\\"B\\\"><b>1. Qual atitude é mais adequada?</b><label><input type=\\\"radio\\\" name=\\\"ps1_c2_1\\\" value=\\\"A\\\"><span>A) TC contrastada obrigatória antes de agir</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c2_1\\\" value=\\\"B\\\"><span>B) Ressuscitar e providenciar controle imediato da hemorragia</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c2_1\\\" value=\\\"C\\\"><span>C) Alta após cristalóide</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c2_1\\\" value=\\\"D\\\"><span>D) Esperar hemoglobina cair</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: B</b> — Instabilidade e FAST positivo levantam indicação de controle emergencial da fonte.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"C\\\"><b>2. Qual afirmação sobre FAST é verdadeira?</b><label><input type=\\\"radio\\\" name=\\\"ps1_c2_2\\\" value=\\\"A\\\"><span>A) Negativo exclui toda hemorragia</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c2_2\\\" value=\\\"B\\\"><span>B) Mostra arteriais com precisão igual à angioTC</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c2_2\\\" value=\\\"C\\\"><span>C) Tem valor no xABCDE, mas não exclui retroperitônio quando negativo</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c2_2\\\" value=\\\"D\\\"><span>D) Dispensa reavaliação</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: C</b> — FAST é ferramenta rápida e com limitações para sangramento retroperitoneal e outras lesões.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"D\\\"><b>3. A pressão arterial inicial normal em outro paciente:</b><label><input type=\\\"radio\\\" name=\\\"ps1_c2_3\\\" value=\\\"A\\\"><span>A) Exclui choque</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c2_3\\\" value=\\\"B\\\"><span>B) Garante lactato normal</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c2_3\\\" value=\\\"C\\\"><span>C) Dispensa exame seriado</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_c2_3\\\" value=\\\"D\\\"><span>D) Não exclui hemorragia compensada</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: D</b> — Sinais periféricos e mecanismo podem revelar hipoperfusão antes da hipotensão.</div></div><button type=\\\"button\\\" class=\\\"retro-check\\\" data-retro-check>Corrigir respostas</button><button type=\\\"button\\\" class=\\\"retro-reset\\\" data-retro-reset>Refazer</button><p class=\\\"retro-result\\\" aria-live=\\\"polite\\\"></p></section></div></details><h2 class=\\\"section-band\\\">TESTE FINAL PARA REFAZER</h2><p class=\\\"subhead\\\">Simulado novo com três perguntas. O gabarito fica oculto até a correção. A conclusão anterior do tema e seu registro de desempenho não são apagados.</p><section class=\\\"retro-quiz\\\" data-set=\\\"ps1_final\\\"><h4>Simulado final — 3 questões</h4><p class=\\\"retro-intro\\\"></p><div class=\\\"retro-q\\\" data-correct=\\\"B\\\"><b>1. Hemorragia ameaçadora de vida antecede qual etapa?</b><label><input type=\\\"radio\\\" name=\\\"ps1_final_1\\\" value=\\\"A\\\"><span>A) D</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_final_1\\\" value=\\\"B\\\"><span>B) x</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_final_1\\\" value=\\\"C\\\"><span>C) E</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_final_1\\\" value=\\\"D\\\"><span>D) C</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: B</b> — A letra x do xABCDE indica controle inicial de hemorragia exsanguinante.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"A\\\"><b>2. FAST negativo no paciente traumatizado significa:</b><label><input type=\\\"radio\\\" name=\\\"ps1_final_2\\\" value=\\\"A\\\"><span>A) Não exclui toda hemorragia e não substitui exame seriado</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_final_2\\\" value=\\\"B\\\"><span>B) Ausência de lesão pélvica</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_final_2\\\" value=\\\"C\\\"><span>C) Não há necessidade de reavaliar</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_final_2\\\" value=\\\"D\\\"><span>D) Alta obrigatória</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: A</b> — O FAST tem limitações, especialmente fora da cavidade peritoneal.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"B\\\"><b>3. Uma mudança súbita na ventilação durante observação requer:</b><label><input type=\\\"radio\\\" name=\\\"ps1_final_3\\\" value=\\\"A\\\"><span>A) Só aguardar laudo</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_final_3\\\" value=\\\"B\\\"><span>B) Reavaliar xABCDE e tratar ameaça imediatamente</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_final_3\\\" value=\\\"C\\\"><span>C) Começar TC antes de qualquer suporte</span></label><label><input type=\\\"radio\\\" name=\\\"ps1_final_3\\\" value=\\\"D\\\"><span>D) Somente exame ortopédico</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: B</b> — Repetir avaliação sistemática após alterações clínicas.</div></div><button type=\\\"button\\\" class=\\\"retro-check\\\" data-retro-check>Corrigir respostas</button><button type=\\\"button\\\" class=\\\"retro-reset\\\" data-retro-reset>Refazer</button><p class=\\\"retro-result\\\" aria-live=\\\"polite\\\"></p></section></section>\\n<section class=\\\"radiology-block\\\"><h2 class=\\\"section-band\\\">EXAMES REAIS COMENTADOS — RX · TC · ANGIO TC · ANGIOGRAFIA</h2><p class=\\\"subhead\\\">Imagens clínicas reais extraídas do manual ATLS 11 enviado. Cada legenda identifica a figura e a página; os achados estão comentados para treino de reconhecimento visual. Nem todas as modalidades são indicadas em todos os pacientes.</p><details class=\\\"modality-study\\\" open><summary>FAST / eFAST — ultrassom real</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"US FAST — líquido livre no espaço hepatorrenal\\\"><h4>US FAST — líquido livre no espaço hepatorrenal</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Faixa anecoica (escura) compatível com líquido livre junto ao fígado/rim no espaço hepatorrenal.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> No contexto de trauma, líquido livre no FAST sugere hemoperitônio; exame negativo não exclui retroperitônio, nem garante ausência de sangramento.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> No paciente instável, FAST ajuda a orientar controle hemorrágico e não substitui decisão clínica.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 6, figura 6-4B, p. 86 (PDF p. 101). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><details class=\\\"modality-study\\\" open><summary>RX comentado</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"RX tórax — pneumotórax hipertensivo e desvio mediastinal\\\"><h4>RX tórax — pneumotórax hipertensivo e desvio mediastinal</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Hemitórax hiperlúcido, colapso pulmonar e desvio mediastinal na apresentação ilustrada pelo ATLS.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> Diferente do hemotórax, que provoca opacidade por líquido; no pneumotórax há ar pleural.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> Em suspeita clínica de tensão, NÃO aguarde RX para descompressão.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 5, figura 5-5B, p. 69 (PDF p. 84). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><details class=\\\"modality-study\\\" open><summary>TC comentada</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"TC axial — contusão pulmonar associada a hemotórax\\\"><h4>TC axial — contusão pulmonar associada a hemotórax</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Opacidades parenquimatosas compatíveis com contusão e coleção pleural hiperdensa.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> Parênquima alterado = contusão; líquido pleural dependente = hemotórax.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> TC somente se o paciente puder ser transportado com segurança e sem atrasar tratamento.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 5, figura 5-9B, p. 73 (PDF p. 88). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><details class=\\\"modality-study\\\" open><summary>AngioTC comentada</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"AngioTC — lesão traumática da aorta torácica\\\"><h4>AngioTC — lesão traumática da aorta torácica</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Alteração focal do contorno aórtico em imagem contrastada de trauma.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> A suspeita surge pelo mecanismo e/ou RX; a angioTC caracteriza a lesão vascular.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> Não encaminhar paciente instável à TC antes das intervenções salvadoras.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 21, figura 21-7B, p. 298 (PDF p. 313). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><details class=\\\"modality-study\\\" open><summary>Angiografia comentada</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"Angiografia — lesão da aorta torácica\\\"><h4>Angiografia — lesão da aorta torácica</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Aortografia do mesmo conjunto do ATLS, demonstrando o defeito vascular.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> A angiografia delineia a luz arterial e pode servir ao planejamento/intervenção; não substitui o ABCDE.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> Exame invasivo: não é etapa obrigatória na avaliação primária.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 21, figura 21-7C, p. 298 (PDF p. 313). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><h3>COMO DIFERENCIAR — TABELA-RESUMO</h3><div class=\\\"table-scroll\\\"><table><thead><tr><th>Diagnóstico ou exame</th><th>Achado que favorece</th><th>Diferencial importante / uso</th></tr></thead><tbody><tr><td>Pneumotórax</td><td>Ar pleural sem marcas vasculares</td><td>No RX: linha pleural; no suspeito de tensão, tratar sem imagem</td></tr><tr><td>Hemotórax</td><td>Opacidade / líquido pleural</td><td>No choque, drenagem e controle de fonte</td></tr><tr><td>Contusão</td><td>Opacidade dentro do pulmão</td><td>TC detecta melhor lesão parenquimatosa</td></tr><tr><td>Lesão vascular</td><td>Defeito vascular contrastado</td><td>AngioTC se estabilidade permite</td></tr></tbody></table></div></section>\",\"2\":\"<h2 class=\\\"section-band\\\">02  •  CHOQUE HEMORRÁGICO</h2>\\n<p class=\\\"subhead\\\">FICHA 02  |  Concluída  |  Teste final 3/3</p>\\n<h3>ÍNDICE DE CHOQUE    ★ PROVA</h3>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">IC = frequência cardíaca ÷ pressão arterial sistólica      |      ≤0,7 normal    •    ≥0,8 alerta    •    ≥1,0 maior risco/mortalidade</div></div>\\n<h3>CLASSIFICAÇÃO TRADICIONAL I–IV (COMPLEMENTAR)    ★ PROVA</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>CLASSE</th><th>PERDA</th><th>VOLUME · 70 KG</th><th>FC (bpm)</th><th>PA</th></tr></thead><tbody><tr><td>I</td><td>&lt;15%</td><td>&lt;750 mL</td><td>&lt;100</td><td>Normal</td></tr><tr><td>II</td><td>15–30%</td><td>750–1.500 mL</td><td>100–120</td><td>Geralmente normal</td></tr><tr><td>III</td><td>30–40%</td><td>1.500–2.000 mL</td><td>120–140</td><td>Baixa</td></tr><tr><td>IV</td><td>&gt;40%</td><td>&gt;2.000 mL</td><td>&gt;140</td><td>Muito baixa</td></tr></tbody></table></div>\\n<p class=\\\"source\\\">ATLS 11: GRAVIDADE PELO DÉFICIT DE BASE</p>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>CATEGORIA</th><th>DÉFICIT DE BASE</th><th>RESPOSTA</th></tr></thead><tbody><tr><td>Menor</td><td>0 a −2</td><td>Sustentada</td></tr><tr><td>Moderada</td><td>−2 a −6</td><td>Geralmente sustentada</td></tr><tr><td>Maior</td><td>−6 a −10</td><td>Transitória possível</td></tr><tr><td>Maior / extrema</td><td>≤ −10</td><td>Mínima ou ausente</td></tr></tbody></table></div>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">SINAIS DE HIPOPERFUSÃO<br>•  Taquicardia, taquipneia, pele fria, enchimento capilar prolongado, alteração mental.<br>•  Lactato e déficit de base podem se alterar antes de hipotensão.<br>•  Hemoglobina pode estar normal no sangramento agudo.</div><div class=\\\"note\\\">RESPONDEDORES    ★ PROVA<br>•  Rápido: melhora sustentada → monitorar/investigar.<br>•  Transitório: melhora e piora → pensar hemorragia contínua.<br>•  Não respondedor: choque persiste → fonte oculta/controle emergencial; rever xABCDE.</div></div>\\n<h3>PEGADINHAS</h3>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">PA normal ≠ perfusão normal. FC normal ≠ ausência de hemorragia (idosos, betabloqueadores, choque misto).</div></div>\\n<p class=\\\"source\\\">ATLS 11ª ed., cap. 6: índice de choque e classificação fisiológica. Classes I–IV = classificação tradicional complementar.</p>\\n<h2 class=\\\"section-band\\\">02  •  TRATAMENTO E LOCALIZAÇÃO</h2>\\n<p class=\\\"subhead\\\">FICHA 02  |  Condutas essenciais</p>\\n<h3>VOLUME E REANIMAÇÃO    ★ PROVA</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>CENÁRIO</th><th>CONDUTA / VALOR</th></tr></thead><tbody><tr><td>Hemorragia significativa</td><td>Preferir sangue total ou componentes balanceados 1:1:1</td></tr><tr><td>Sangue temporariamente indisponível</td><td>250–500 mL cristalóide isotônico no adulto (temporário)</td></tr><tr><td>Débito urinário adulto</td><td>Meta aproximada ≥0,5 mL/kg/h, como tendência de perfusão</td></tr><tr><td>TXA em paciente selecionado</td><td>Até 3 h: 1 g IV inicial + 1 g em 8 h; ou protocolo alternativo</td></tr><tr><td>Hipotensão permissiva</td><td>PAS em torno de 90 mmHg em selecionados SEM TCE/LME</td></tr></tbody></table></div>\\n<h3>ESCORE ABC — TRANSFUSÃO MACIÇA</h3>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">PAS ≤90 (+1)  •  FC ≥120 (+1)  •  FAST positivo (+1)  •  trauma penetrante no tronco (+1).   ABC ≥2 = maior risco de transfusão maciça.</div></div>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">FONTES DE HEMORRAGIA<br>•  Tórax; abdome; pelve/retroperitônio; fêmur e tecidos moles; exterior.<br>HEMORRAGIA PÉLVICA<br>•  Binder nos trocânteres maiores.<br>•  Sangramento venoso/ósseo: tamponamento pré-peritoneal e estabilização.<br>•  Sangramento arterial: angioembolização se disponível.</div><div class=\\\"note\\\">CHOQUE NEUROGÊNICO × HEMORRÁGICO<br>•  Hemorrágico: mais comum, tipicamente taquicardia + pele fria.<br>•  Neurogênico: lesão alta, hipotensão + bradicardia + pele quente.<br>•  Podem coexistir; excluir/tratar hemorragia antes de atribuir tudo à medula.<br>•  Noradrenalina pode ser usada para vasoplegia neurogênica, não substitui sangue.</div></div>\\n<h3>MUITO COBRADO</h3>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">eFAST negativo NÃO exclui sangramento pélvico/retroperitoneal. Trauma instável com FAST positivo pode exigir cirurgia imediata, sem tomografia.</div></div>\\n<p class=\\\"source\\\">ATLS 11ª ed. caps. 6, 7, 10 e 22. TXA e metas de pressão dependem do perfil do trauma e protocolo local.</p>\\n<section class=\\\"retro-practice\\\"><h2 class=\\\"section-band\\\">CASOS CLÍNICOS INTERATIVOS</h2><p class=\\\"subhead\\\">Casos adicionais de treino elaborados com base nos conceitos do ATLS 11. Os resultados dos exercícios abaixo são independentes das notas históricas.</p><details class=\\\"retro-case\\\"><summary>Caso 1 — Choque hemorrágico com FAST positivo <span>3 questões</span></summary><div class=\\\"retro-case-content\\\"><p class=\\\"clinical\\\"><b>Vinheta:</b> Motociclista apresenta PA 84/52, FC 142, enchimento capilar prolongado, FAST positivo e dor abdominal.</p><section class=\\\"retro-quiz\\\" data-set=\\\"ps2_c1\\\"><h4>Resolva o caso antes de abrir a correção</h4><p class=\\\"retro-intro\\\"></p><div class=\\\"retro-q\\\" data-correct=\\\"A\\\"><b>1. O diagnóstico sindrômico prioritário é:</b><label><input type=\\\"radio\\\" name=\\\"ps2_c1_1\\\" value=\\\"A\\\"><span>A) Choque hemorrágico traumático</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c1_1\\\" value=\\\"B\\\"><span>B) Choque neurogênico isolado</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c1_1\\\" value=\\\"C\\\"><span>C) Hiperventilação ansiosa</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c1_1\\\" value=\\\"D\\\"><span>D) Pneumonia</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: A</b> — Mecanismo, instabilidade e FAST positivo sustentam hemorragia intra-abdominal.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"C\\\"><b>2. A prioridade após medidas iniciais é:</b><label><input type=\\\"radio\\\" name=\\\"ps2_c1_2\\\" value=\\\"A\\\"><span>A) Aguardar revisão após seis horas</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c1_2\\\" value=\\\"B\\\"><span>B) TC antes de qualquer ressuscitação</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c1_2\\\" value=\\\"C\\\"><span>C) Controle da fonte e reanimação hemostática</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c1_2\\\" value=\\\"D\\\"><span>D) Apenas cristaloide prolongado</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: C</b> — A fonte de sangramento exige tratamento definitivo, associado a hemoderivados quando indicado.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"B\\\"><b>3. Hemoglobina inicialmente normal:</b><label><input type=\\\"radio\\\" name=\\\"ps2_c1_3\\\" value=\\\"A\\\"><span>A) Descarta perda aguda</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c1_3\\\" value=\\\"B\\\"><span>B) Pode ocorrer na hemorragia aguda</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c1_3\\\" value=\\\"C\\\"><span>C) Contraindica transfusão em qualquer caso</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c1_3\\\" value=\\\"D\\\"><span>D) Diagnostica choque neurogênico</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: B</b> — A Hb pode não refletir perda sanguínea imediata.</div></div><button type=\\\"button\\\" class=\\\"retro-check\\\" data-retro-check>Corrigir respostas</button><button type=\\\"button\\\" class=\\\"retro-reset\\\" data-retro-reset>Refazer</button><p class=\\\"retro-result\\\" aria-live=\\\"polite\\\"></p></section></div></details><details class=\\\"retro-case\\\"><summary>Caso 2 — Hemotórax e choque <span>3 questões</span></summary><div class=\\\"retro-case-content\\\"><p class=\\\"clinical\\\"><b>Vinheta:</b> Paciente com trauma torácico após colisão tem hipotensão, taquicardia, MV reduzido e velamento extenso em um hemitórax.</p><section class=\\\"retro-quiz\\\" data-set=\\\"ps2_c2\\\"><h4>Resolva o caso antes de abrir a correção</h4><p class=\\\"retro-intro\\\"></p><div class=\\\"retro-q\\\" data-correct=\\\"D\\\"><b>1. O achado radiológico sugere:</b><label><input type=\\\"radio\\\" name=\\\"ps2_c2_1\\\" value=\\\"A\\\"><span>A) Pneumotórax pequeno</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c2_1\\\" value=\\\"B\\\"><span>B) Contusão cardíaca</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c2_1\\\" value=\\\"C\\\"><span>C) Perda de volume lobar isolada</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c2_1\\\" value=\\\"D\\\"><span>D) Hemotórax importante</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: D</b> — Velamento unilateral em trauma com instabilidade sugere hemotórax até prova em contrário.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"A\\\"><b>2. Qual medida trata o componente pleural de forma inicial?</b><label><input type=\\\"radio\\\" name=\\\"ps2_c2_2\\\" value=\\\"A\\\"><span>A) Drenagem pleural quando indicada</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c2_2\\\" value=\\\"B\\\"><span>B) Apenas espirometria</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c2_2\\\" value=\\\"C\\\"><span>C) Tomografia obrigatória apesar de choque</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c2_2\\\" value=\\\"D\\\"><span>D) Tosse vigorosa como única intervenção</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: A</b> — Dreno pleural pode ser terapêutico e ajuda a quantificar sangramento.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"C\\\"><b>3. A decisão sobre cirurgia considera:</b><label><input type=\\\"radio\\\" name=\\\"ps2_c2_3\\\" value=\\\"A\\\"><span>A) Somente cor do dreno</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c2_3\\\" value=\\\"B\\\"><span>B) Apenas Hb isolada</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c2_3\\\" value=\\\"C\\\"><span>C) Choque e sangramento persistente além do débito</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_c2_3\\\" value=\\\"D\\\"><span>D) Unicamente idade</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: C</b> — ATLS 11 enfatiza fisiologia e continuidade da hemorragia.</div></div><button type=\\\"button\\\" class=\\\"retro-check\\\" data-retro-check>Corrigir respostas</button><button type=\\\"button\\\" class=\\\"retro-reset\\\" data-retro-reset>Refazer</button><p class=\\\"retro-result\\\" aria-live=\\\"polite\\\"></p></section></div></details><h2 class=\\\"section-band\\\">TESTE FINAL PARA REFAZER</h2><p class=\\\"subhead\\\">Simulado novo com três perguntas. O gabarito fica oculto até a correção. A conclusão anterior do tema e seu registro de desempenho não são apagados.</p><section class=\\\"retro-quiz\\\" data-set=\\\"ps2_final\\\"><h4>Simulado final — 3 questões</h4><p class=\\\"retro-intro\\\"></p><div class=\\\"retro-q\\\" data-correct=\\\"C\\\"><b>1. Qual achado aponta para choque apesar de PA inicialmente preservada?</b><label><input type=\\\"radio\\\" name=\\\"ps2_final_1\\\" value=\\\"A\\\"><span>A) Pele quente após banho</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_final_1\\\" value=\\\"B\\\"><span>B) Saturação 99%</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_final_1\\\" value=\\\"C\\\"><span>C) Taquicardia e enchimento capilar prolongado</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_final_1\\\" value=\\\"D\\\"><span>D) Temperatura externa normal</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: C</b> — A perfusão pode cair antes de hipotensão manifesta.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"B\\\"><b>2. Paciente chocado com FAST positivo após trauma contuso:</b><label><input type=\\\"radio\\\" name=\\\"ps2_final_2\\\" value=\\\"A\\\"><span>A) Aguardar queda de Hb</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_final_2\\\" value=\\\"B\\\"><span>B) Priorizar controle da fonte hemorrágica</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_final_2\\\" value=\\\"C\\\"><span>C) Repetir FAST por 24h sem agir</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_final_2\\\" value=\\\"D\\\"><span>D) Suspender reanimação</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: B</b> — Instabilidade e achados compatíveis com hemorragia exigem tratamento urgente.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"D\\\"><b>3. TC contrastada em trauma:</b><label><input type=\\\"radio\\\" name=\\\"ps2_final_3\\\" value=\\\"A\\\"><span>A) É sempre obrigatória em qualquer instabilidade</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_final_3\\\" value=\\\"B\\\"><span>B) Dispensa exame físico</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_final_3\\\" value=\\\"C\\\"><span>C) Exclui choque</span></label><label><input type=\\\"radio\\\" name=\\\"ps2_final_3\\\" value=\\\"D\\\"><span>D) É melhor reservada ao paciente suficientemente estável para realizar o exame</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: D</b> — A estabilidade fisiológica determina segurança para exames avançados.</div></div><button type=\\\"button\\\" class=\\\"retro-check\\\" data-retro-check>Corrigir respostas</button><button type=\\\"button\\\" class=\\\"retro-reset\\\" data-retro-reset>Refazer</button><p class=\\\"retro-result\\\" aria-live=\\\"polite\\\"></p></section></section>\\n<section class=\\\"radiology-block\\\"><h2 class=\\\"section-band\\\">EXAMES REAIS COMENTADOS — RX · TC · ANGIO TC · ANGIOGRAFIA</h2><p class=\\\"subhead\\\">Imagens clínicas reais extraídas do manual ATLS 11 enviado. Cada legenda identifica a figura e a página; os achados estão comentados para treino de reconhecimento visual. Nem todas as modalidades são indicadas em todos os pacientes.</p><details class=\\\"modality-study\\\" open><summary>FAST / eFAST — ultrassom real</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"US FAST — líquido livre no espaço hepatorrenal\\\"><h4>US FAST — líquido livre no espaço hepatorrenal</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Faixa anecoica (escura) compatível com líquido livre junto ao fígado/rim no espaço hepatorrenal.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> No contexto de trauma, líquido livre no FAST sugere hemoperitônio; exame negativo não exclui retroperitônio, nem garante ausência de sangramento.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> No paciente instável, FAST ajuda a orientar controle hemorrágico e não substitui decisão clínica.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 6, figura 6-4B, p. 86 (PDF p. 101). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><details class=\\\"modality-study\\\" open><summary>RX comentado</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"RX tórax — hemotórax maciço\\\"><h4>RX tórax — hemotórax maciço</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Opacificação extensa de um hemitórax pela coleção pleural sanguínea.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> Líquido pleural opacifica; pneumotórax geralmente causa hiperlucência.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> No choque, a fisiologia manda mais do que uma única imagem.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 6, figura 6-3, p. 85 (PDF p. 100). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><details class=\\\"modality-study\\\" open><summary>TC comentada</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"TC axial — contusão pulmonar associada a hemotórax\\\"><h4>TC axial — contusão pulmonar associada a hemotórax</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Consolidação/contusão pulmonar mais coleção de conteúdo pleural dependente.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> Hemotórax é pleural; contusão está dentro do pulmão.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> FAST negativo não exclui perda torácica ou pélvica.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 5, figura 5-9B, p. 73 (PDF p. 88). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><details class=\\\"modality-study\\\" open><summary>AngioTC comentada</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"AngioTC — lesão traumática da aorta torácica\\\"><h4>AngioTC — lesão traumática da aorta torácica</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Lesão da aorta torácica após trauma de desaceleração.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> AngioTC demonstra integridade vascular; RX indica suspeita, mas não fecha a lesão.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> Exame para paciente suficientemente estável.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 21, figura 21-7B, p. 298 (PDF p. 313). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><details class=\\\"modality-study\\\" open><summary>Angiografia comentada</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"Angiografia — lesão da aorta torácica\\\"><h4>Angiografia — lesão da aorta torácica</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Aortografia com irregularidade traumática da luz da aorta.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> Útil em cenários selecionados; interpretação depende do mecanismo e da circulação.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> Não se indica angiografia de rotina para todo choque hemorrágico.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 21, figura 21-7C, p. 298 (PDF p. 313). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><h3>COMO DIFERENCIAR — TABELA-RESUMO</h3><div class=\\\"table-scroll\\\"><table><thead><tr><th>Diagnóstico ou exame</th><th>Achado que favorece</th><th>Diferencial importante / uso</th></tr></thead><tbody><tr><td>Choque hemorrágico torácico</td><td>Hemotórax em RX/eFAST</td><td>Pode coexistir com lesão pulmonar</td></tr><tr><td>Hemorragia abdominal</td><td>FAST com líquido livre</td><td>FAST não determina órgão lesionado</td></tr><tr><td>Vaso torácico</td><td>Lesão contrastada na angioTC</td><td>Só paciente suficientemente estável</td></tr></tbody></table></div></section>\",\"3\":\"<h2 class=\\\"section-band\\\">03  •  TRANSFUSÃO MACIÇA</h2>\\n<p class=\\\"subhead\\\">FICHA 03  |  Concluída  |  Teste final 3/3</p>\\n<h3>CRITÉRIOS E ESTRATÉGIAS    ★ PROVA</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>CRITÉRIO</th><th>VALOR / CONDUTA</th></tr></thead><tbody><tr><td>Definição clássica retrospectiva</td><td>≥10 U concentrado de hemácias em 24 h</td></tr><tr><td>Critério dinâmico</td><td>≥4 U em 1 h com previsão de necessidade continuada</td></tr><tr><td>Escore ABC</td><td>≥2 sugere maior necessidade; não esperar dez bolsas</td></tr><tr><td>Reposição inicial</td><td>Sangue total adequado ou hemocomponentes 1:1:1</td></tr><tr><td>Evitar</td><td>Grandes volumes de cristaloides e atraso no controle da fonte</td></tr></tbody></table></div>\\n<h3>HEMOCOMPONENTES — DOSES PARA PROVA    ★ PROVA</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>PRODUTO</th><th>PARA QUE SERVE</th><th>DOSE ADULTA / REGRA</th></tr></thead><tbody><tr><td>Concentrado de hemácias</td><td>Transporte de O₂</td><td>1 U aumenta Hb ~1 g/dL sem sangramento ativo</td></tr><tr><td>Plasma fresco congelado</td><td>Fatores da coagulação</td><td>10–15 mL/kg em situações indicadas</td></tr><tr><td>Plaquetas</td><td>Hemostasia primária</td><td>1 dose terapêutica (aférese ou equivalente)</td></tr><tr><td>Crioprecipitado</td><td>Repõe fibrinogênio</td><td>~10 U convencionais, ou equivalente</td></tr></tbody></table></div>\\n<h3>LABORATÓRIO — NORMAL × META EM HEMORRAGIA</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>EXAME</th><th>REFERÊNCIA</th><th>META USUAL NO SANGRAMENTO</th></tr></thead><tbody><tr><td>Plaquetas</td><td>150–450 mil/mm³</td><td>&gt;50 mil/mm³</td></tr><tr><td>Fibrinogênio</td><td>150–400 mg/dL*</td><td>&gt;150–200 mg/dL</td></tr><tr><td>INR</td><td>0,8–1,2</td><td>Geralmente &lt;1,5</td></tr><tr><td>TP / TTPa</td><td>11–13,5 s / 25–35 s</td><td>Evitar prolongamento</td></tr><tr><td>Cálcio ionizado</td><td>1,12–1,32 mmol/L</td><td>Faixa normal</td></tr><tr><td>Potássio</td><td>3,5–5,0 mEq/L</td><td>Faixa normal</td></tr><tr><td>pH arterial</td><td>7,35–7,45</td><td>Corrigir acidose</td></tr><tr><td>Temperatura central</td><td>36–37,5 °C</td><td>Evitar &lt;35 °C</td></tr><tr><td>Lactato</td><td>Geralmente &lt;2 mmol/L</td><td>Queda progressiva</td></tr></tbody></table></div>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">★ PEGADINHA: INR normal não exclui fibrinogênio crítico. Hipofibrinogenemia → crio; plaquetopenia → plaquetas; múltiplos fatores → plasma.</div></div>\\n<p class=\\\"explainer\\\">*Referência do ATLS: fibrinogênio 150–400 mg/dL (não gestantes). Metas e doses de hemoterapia são complementares e variam conforme protocolo.</p>\\n<h2 class=\\\"section-band\\\">03  •  CONTROLE DE DANOS E COMPLICAÇÕES</h2>\\n<p class=\\\"subhead\\\">FICHA 03  |  Quadro de bolso</p>\\n<h3>TRÍADE LETAL E CIRURGIA ABREVIADA    ★ PROVA</h3>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">HIPOTERMIA (&lt;35 °C)  +  ACIDOSE (pH baixo)  +  COAGULOPATIA   →   interromper espiral fisiológica.</div></div>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>FASE</th><th>OBJETIVO</th></tr></thead><tbody><tr><td>1 · Cirurgia abreviada</td><td>Controle de hemorragia/contaminação; fechamento temporário quando indicado</td></tr><tr><td>2 · UTI</td><td>Aquecimento, hemostasia, correção de hipoperfusão, coagulopatia e eletrólitos</td></tr><tr><td>3 · Reoperação</td><td>Reparos definitivos quando estável; frequentemente 24–48 h, individualizar</td></tr></tbody></table></div>\\n<h3>COMPLICAÇÕES DA TRANSFUSÃO</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>EVENTO</th><th>MECANISMO / PISTA</th></tr></thead><tbody><tr><td>Hipocalcemia</td><td>Citrato quelante de cálcio → disfunção cardíaca/coagulação</td></tr><tr><td>Hipercalemia</td><td>Potássio do sangue armazenado; ondas T apiculadas, QRS largo</td></tr><tr><td>Hipotermia</td><td>Produtos frios e exposição</td></tr><tr><td>TRALI</td><td>Lesão pulmonar aguda sem sobrecarga hidrostática</td></tr><tr><td>TACO</td><td>Sobrecarga circulatória / congestão pulmonar</td></tr><tr><td>Reação hemolítica</td><td>Febre, hipotensão, hemoglobinúria → interromper transfusão</td></tr></tbody></table></div>\\n<h3>HIPERCALEMIA COM ECG ALTERADO — ADULTO    ★ PROVA</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>OBJETIVO</th><th>MEDIDA REFERENCIAL</th></tr></thead><tbody><tr><td>Estabilizar coração</td><td>Gluconato de cálcio 10%: 10–20 mL IV; monitorizar ECG</td></tr><tr><td>Shift intracelular</td><td>Insulina regular 10 UI IV + glicose 25 g IV; monitorar glicemia</td></tr><tr><td>Adjuvante</td><td>Salbutamol nebulizado 10–20 mg</td></tr><tr><td>Eliminar potássio</td><td>Estratégia renal/diálise conforme indicação; repetir K e ECG</td></tr></tbody></table></div>\\n<h3>SÍNDROME COMPARTIMENTAL ABDOMINAL — WSACS</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>PIA</th><th>GRAU</th></tr></thead><tbody><tr><td>12–15 mmHg</td><td>I</td></tr><tr><td>16–20 mmHg</td><td>II</td></tr><tr><td>21–25 mmHg</td><td>III</td></tr><tr><td>&gt;25 mmHg</td><td>IV</td></tr></tbody></table></div>\\n<div class=\\\"note-grid\\\"><div class=\\\"note\\\">HIA: PIA sustentada ≥12 mmHg. SCA: PIA sustentada &gt;20 mmHg + nova disfunção orgânica. PPA = PAM − PIA. Síndrome refratária → descompressão cirúrgica.</div></div>\\n<p class=\\\"explainer\\\">TXA: em sangramento traumático selecionado, até 3 h; esquema clássico 1 g IV + 1 g em 8 h. Doses de emergência e critérios WSACS: referências complementares, não prescrição individual.</p>\\n<p class=\\\"subhead\\\">FICHA 03  |  REAÇÕES TRANSFUSIONAIS  |  ★★ PROVA</p>\\n<h3>TRALI × TACO × REAÇÃO HEMOLÍTICA AGUDA — DIFERENCIAÇÃO</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>Pista</th><th>TRALI</th><th>TACO</th><th>Hemolítica aguda</th></tr></thead><tbody><tr><td>Mecanismo</td><td>Lesão pulmonar inflamatória</td><td>Sobrecarga hidrostática</td><td>Destruição de hemácias; clássica: incompatibilidade ABO</td></tr><tr><td>Tempo</td><td>Durante ou ≤6 h</td><td>Durante ou ≤12 h</td><td>Durante ou ≤24 h; muitas vezes minutos</td></tr><tr><td>Pressão arterial</td><td>Normal ou hipotensão</td><td>Muitas vezes hipertensão</td><td>Pode haver hipotensão/choque</td></tr><tr><td>Quadro</td><td>Hipoxemia + infiltrados bilaterais, sem sobrecarga</td><td>Dispneia, congestão, JVP alta, balanço +</td><td>Febre, calafrios, dor lombar, hemoglobinúria</td></tr><tr><td>Exames/pistas</td><td>Edema não cardiogênico; ausência de hipertensão atrial esquerda como causa principal</td><td>BNP/NT-proBNP ↑ pode apoiar; congestão e balanço +</td><td>DAT/Coombs direto, DHL ↑, bilirrubina indireta ↑, haptoglobina ↓</td></tr><tr><td>Conduta</td><td>Parar bolsa; O₂ e suporte ventilatório; não diurético de rotina</td><td>Parar bolsa; O₂; diurético se apropriado</td><td>Parar bolsa; suporte hemodinâmico/renal, investigação hemolítica</td></tr></tbody></table></div>\\n<h3>CONDUTA IMEDIATA COMUM — SUSPEITOU DE REAÇÃO GRAVE</h3>\\n<p class=\\\"explainer\\\">1  INTERROMPER A TRANSFUSÃO.  2  Avaliar ABC, sinais vitais e oxigenação.  3  Manter acesso venoso com SF 0,9% em equipo novo.  4  Conferir paciente, prescrição e identificação da bolsa.  5  Notificar banco de sangue/hemoterapia, encaminhar bolsa e amostras conforme protocolo.</p>\\n<h3>DIFERENÇAS ESSENCIAIS — AS PEGADINHAS</h3>\\n<div class=\\\"table-scroll\\\"><table><thead><tr><th>TRALI</th><th>TACO</th><th>HEMÓLISE</th></tr></thead><tbody><tr><td>Não é edema por excesso de volume. Suporte respiratório; diurético não trata o mecanismo.</td><td>Sobrecarga circulatória; melhora da congestão com diurético quando indicado.</td><td>Incompatibilidade ABO é a causa clássica de prova; risco de choque, CIVD e lesão renal aguda.</td></tr><tr><td>Pode ocorrer mesmo com pequeno volume transfundido.</td><td>Risco ↑: idosos, insuficiência cardíaca/renal, infusão rápida.</td><td>Febre e dor lombar durante transfusão = interromper e investigar imediatamente.</td></tr></tbody></table></div>\\n<h3>CRITÉRIOS E OBSERVAÇÕES PARA NÃO ERRAR A QUESTÃO</h3>\\n<p class=\\\"explainer\\\">TRALI: início durante ou até 6 h, hipoxemia e edema pulmonar bilateral não explicado principalmente por sobrecarga. TACO: critérios de hemovigilância podem incluir manifestações até 12 h após a transfusão; não depende apenas de hipertensão ou BNP. Hemólise aguda: verificar compatibilidade e coleta pré/pós, hemograma, DHL, bilirrubina, haptoglobina, hemoglobinúria, creatinina e coagulação.</p>\\n<h3>MINIQUESTÕES-RELÂMPAGO</h3>\\n<p class=\\\"explainer\\\">• Dispneia + hipertensão + turgência jugular após PFC → TACO.<br>• Hipoxemia + infiltrados bilaterais + ausência de sobrecarga durante transfusão → TRALI.<br>• Febre + calafrios + dor lombar + urina escura → reação hemolítica aguda.</p>\\n<p class=\\\"source\\\">FONTES: complemento de hemovigilância e hemoterapia; diferenciação TRALI/TACO e critérios temporais não foram identificados no trecho consultado do ATLS 11. Resumo para prova; protocolos locais podem diferir.</p>\\n<section class=\\\"retro-practice\\\"><h2 class=\\\"section-band\\\">CASOS CLÍNICOS INTERATIVOS</h2><p class=\\\"subhead\\\">Casos adicionais de treino elaborados com base nos conceitos do ATLS 11. Os resultados dos exercícios abaixo são independentes das notas históricas.</p><details class=\\\"retro-case\\\"><summary>Caso 1 — Coagulopatia no trauma e transfusão maciça <span>3 questões</span></summary><div class=\\\"retro-case-content\\\"><p class=\\\"clinical\\\"><b>Vinheta:</b> Paciente com trauma abdominal grave, hipotermia, acidose e hemorragia ativa recebe múltiplas transfusões.</p><section class=\\\"retro-quiz\\\" data-set=\\\"ps3_c1\\\"><h4>Resolva o caso antes de abrir a correção</h4><p class=\\\"retro-intro\\\"></p><div class=\\\"retro-q\\\" data-correct=\\\"B\\\"><b>1. Qual princípio é prioritário?</b><label><input type=\\\"radio\\\" name=\\\"ps3_c1_1\\\" value=\\\"A\\\"><span>A) Cristaloide ilimitado como terapia principal</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c1_1\\\" value=\\\"B\\\"><span>B) Controle de danos e reanimação hemostática</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c1_1\\\" value=\\\"C\\\"><span>C) Corrigir apenas o potássio</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c1_1\\\" value=\\\"D\\\"><span>D) Aguardar INR normal antes de controlar fonte</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: B</b> — Hemorragia não se resolve sem controle da fonte e reposição hemostática.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"C\\\"><b>2. A hipotermia contribui para:</b><label><input type=\\\"radio\\\" name=\\\"ps3_c1_2\\\" value=\\\"A\\\"><span>A) Melhor função plaquetária</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c1_2\\\" value=\\\"B\\\"><span>B) Neutralização espontânea do sangramento</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c1_2\\\" value=\\\"C\\\"><span>C) Piora da coagulação</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c1_2\\\" value=\\\"D\\\"><span>D) Ausência de acidose</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: C</b> — Hipotermia agrava coagulopatia e deve ser prevenida.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"A\\\"><b>3. Na estratégia balanceada, é comum utilizar:</b><label><input type=\\\"radio\\\" name=\\\"ps3_c1_3\\\" value=\\\"A\\\"><span>A) Hemocomponentes em proporções balanceadas segundo protocolo</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c1_3\\\" value=\\\"B\\\"><span>B) Apenas plaquetas sempre</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c1_3\\\" value=\\\"C\\\"><span>C) Apenas cristaloide</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c1_3\\\" value=\\\"D\\\"><span>D) Somente albumina</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: A</b> — Reanimação baseada em sangue/componentes balanceados é usual no choque hemorrágico grave.</div></div><button type=\\\"button\\\" class=\\\"retro-check\\\" data-retro-check>Corrigir respostas</button><button type=\\\"button\\\" class=\\\"retro-reset\\\" data-retro-reset>Refazer</button><p class=\\\"retro-result\\\" aria-live=\\\"polite\\\"></p></section></div></details><details class=\\\"retro-case\\\"><summary>Caso 2 — TC contrastada e lesão vascular <span>3 questões</span></summary><div class=\\\"retro-case-content\\\"><p class=\\\"clinical\\\"><b>Vinheta:</b> Trauma de desaceleração em paciente inicialmente estável apresenta mediastino alargado ao RX; angioTC mostra lesão aórtica.</p><section class=\\\"retro-quiz\\\" data-set=\\\"ps3_c2\\\"><h4>Resolva o caso antes de abrir a correção</h4><p class=\\\"retro-intro\\\"></p><div class=\\\"retro-q\\\" data-correct=\\\"C\\\"><b>1. Qual exame caracteriza melhor a lesão vascular no paciente estável?</b><label><input type=\\\"radio\\\" name=\\\"ps3_c2_1\\\" value=\\\"A\\\"><span>A) RX isolado</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c2_1\\\" value=\\\"B\\\"><span>B) FAST abdominal isolado</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c2_1\\\" value=\\\"C\\\"><span>C) AngioTC com contraste</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c2_1\\\" value=\\\"D\\\"><span>D) Radiografia de costelas</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: C</b> — AngioTC demonstra a lesão da parede vascular e suas relações anatômicas.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"B\\\"><b>2. Se houver deterioração hemodinâmica, qual princípio prevalece?</b><label><input type=\\\"radio\\\" name=\\\"ps3_c2_2\\\" value=\\\"A\\\"><span>A) Descrever toda imagem antes do ABCDE</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c2_2\\\" value=\\\"B\\\"><span>B) Tratar ameaças e reavaliar xABCDE imediatamente</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c2_2\\\" value=\\\"C\\\"><span>C) Continuar estudo eletivo</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c2_2\\\" value=\\\"D\\\"><span>D) Suspender reanimação</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: B</b> — A fisiologia define urgência e limita exames demorados.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"D\\\"><b>3. O achado de mediastino alargado em RX:</b><label><input type=\\\"radio\\\" name=\\\"ps3_c2_3\\\" value=\\\"A\\\"><span>A) É diagnóstico definitivo de lesão aórtica</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c2_3\\\" value=\\\"B\\\"><span>B) Exclui trauma vascular</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c2_3\\\" value=\\\"C\\\"><span>C) Significa sempre hemotórax</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_c2_3\\\" value=\\\"D\\\"><span>D) É sinal de suspeita, a confirmar no contexto apropriado</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: D</b> — O RX indica suspeita; a angioTC pode confirmar e classificar em pacientes estáveis.</div></div><button type=\\\"button\\\" class=\\\"retro-check\\\" data-retro-check>Corrigir respostas</button><button type=\\\"button\\\" class=\\\"retro-reset\\\" data-retro-reset>Refazer</button><p class=\\\"retro-result\\\" aria-live=\\\"polite\\\"></p></section></div></details><h2 class=\\\"section-band\\\">TESTE FINAL PARA REFAZER</h2><p class=\\\"subhead\\\">Simulado novo com três perguntas. O gabarito fica oculto até a correção. A conclusão anterior do tema e seu registro de desempenho não são apagados.</p><section class=\\\"retro-quiz\\\" data-set=\\\"ps3_final\\\"><h4>Simulado final — 3 questões</h4><p class=\\\"retro-intro\\\"></p><div class=\\\"retro-q\\\" data-correct=\\\"B\\\"><b>1. Prioridade na hemorragia grave com coagulopatia:</b><label><input type=\\\"radio\\\" name=\\\"ps3_final_1\\\" value=\\\"A\\\"><span>A) Soro fisiológico ilimitado</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_final_1\\\" value=\\\"B\\\"><span>B) Controle da fonte + reanimação hemostática</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_final_1\\\" value=\\\"C\\\"><span>C) Normalizar INR isoladamente</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_final_1\\\" value=\\\"D\\\"><span>D) Só monitorar lactato</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: B</b> — Repor sangue sem controlar sangramento não resolve o choque.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"A\\\"><b>2. Qual condição agrava a coagulopatia traumática?</b><label><input type=\\\"radio\\\" name=\\\"ps3_final_2\\\" value=\\\"A\\\"><span>A) Hipotermia</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_final_2\\\" value=\\\"B\\\"><span>B) Normotermia</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_final_2\\\" value=\\\"C\\\"><span>C) Melhora de perfusão</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_final_2\\\" value=\\\"D\\\"><span>D) Controle rápido da fonte</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: A</b> — A hipotermia compromete hemostasia.</div></div><div class=\\\"retro-q\\\" data-correct=\\\"C\\\"><b>3. A angioTC ajuda a reconhecer:</b><label><input type=\\\"radio\\\" name=\\\"ps3_final_3\\\" value=\\\"A\\\"><span>A) Somente atelectasia</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_final_3\\\" value=\\\"B\\\"><span>B) Somente fraturas dentárias</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_final_3\\\" value=\\\"C\\\"><span>C) Lesões vasculares contrastadas, como pseudoaneurisma e dissecção</span></label><label><input type=\\\"radio\\\" name=\\\"ps3_final_3\\\" value=\\\"D\\\"><span>D) Só pneumomediastino</span></label><div class=\\\"retro-feedback\\\" hidden><b>Gabarito: C</b> — Contraste vascular permite avaliar integridade arterial.</div></div><button type=\\\"button\\\" class=\\\"retro-check\\\" data-retro-check>Corrigir respostas</button><button type=\\\"button\\\" class=\\\"retro-reset\\\" data-retro-reset>Refazer</button><p class=\\\"retro-result\\\" aria-live=\\\"polite\\\"></p></section></section>\\n<section class=\\\"radiology-block\\\"><h2 class=\\\"section-band\\\">EXAMES REAIS COMENTADOS — RX · TC · ANGIO TC · ANGIOGRAFIA</h2><p class=\\\"subhead\\\">Imagens clínicas reais extraídas do manual ATLS 11 enviado. Cada legenda identifica a figura e a página; os achados estão comentados para treino de reconhecimento visual. Nem todas as modalidades são indicadas em todos os pacientes.</p><details class=\\\"modality-study\\\" open><summary>RX comentado</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,\\\" alt=\\\"RX tórax — alargamento do mediastino\\\"><h4>RX tórax — alargamento do mediastino</h4><div class=\\\"exam-what\\\"><b>O que está alterado?</b> Alargamento mediastinal em trauma de desaceleração.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar?</b> É sinal indireto de lesão aórtica; outros processos podem alargar o mediastino.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> RX não confirma sozinho lesão aórtica.</div><p class=\\\"exam-source\\\"><b>Fonte:</b> ATLS 11, cap. 21, figura 21-7A, p. 298 (PDF p. 313). <span>Imagem clínica original do material de referência fornecido para estudo; não é imagem gerada por IA.</span></p></article></div></details><details class=\\\"modality-study\\\" open><summary>TC comentada</summary><div class=\\\"modality-inner\\\"><article class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/jpeg;base64,");
